import java.io.IOException;
import java.nio.file.*;

public class CopyDemo {
    public static void main(String[] args) throws IOException {
        Path src = Path.of("a.txt");
        Path dst = Path.of("b.txt");
        Files.writeString(src, "new");
        Files.writeString(dst, "old");
        try {
            Files.copy(src, dst);
        } catch (FileAlreadyExistsException e) {
            System.out.print("exists ");
        }
        Files.copy(src, dst, StandardCopyOption.REPLACE_EXISTING);
        System.out.print(Files.readString(dst));
    }
}

import java.io.IOException;
import java.nio.file.*;
import java.util.stream.Stream;

public class Count {
    public static void main(String[] args) throws IOException {
        // existing tree:  root/a.txt  and  root/sub/b.txt
        Path root = Path.of("root");
        try (Stream<Path> s1 = Files.list(root);
             Stream<Path> s2 = Files.walk(root);
             Stream<Path> s3 = Files.walk(root, 1)) {
            System.out.println(s1.count() + " " + s2.count() + " " + s3.count());
        }
    }
}

import java.io.IOException;
import java.nio.file.*;

public class Cleaner {
    public static void main(String[] args) throws IOException {
        // root/sub/b.txt exists; ghost.txt does not exist
        try {
            Files.delete(Path.of("root/sub"));
            System.out.print("deleted ");
        } catch (DirectoryNotEmptyException e) {
            System.out.print("notEmpty ");
        } catch (IOException e) {
            System.out.print("io ");
        }
        System.out.print(Files.deleteIfExists(Path.of("ghost.txt")) + " ");
        try {
            Files.delete(Path.of("ghost.txt"));
        } catch (NoSuchFileException e) {
            System.out.print("missing");
        }
    }
}

import java.io.IOException;
import java.nio.file.*;

public class Same {
    public static void main(String[] args) throws IOException {
        // the file data/f.txt exists in the working directory
        Path p1 = Path.of("data/../data/f.txt");
        Path p2 = Path.of("data/f.txt");
        System.out.println(p1.equals(p2) + " "
            + p1.normalize().equals(p2) + " "
            + Files.isSameFile(p1, p2) + " "
            + p2.equals(p2.toAbsolutePath()));
    }
}

import java.io.IOException;
import java.nio.file.*;
import java.util.stream.Stream;

public class Finder {
    public static void main(String[] args) throws IOException {
        // root/a.txt, root/sub/b.txt, root/sub/deep/c.txt, root/sub/deep/d.log
        try (Stream<Path> s = Files.find(Path.of("root"), 2,
                (p, attr) -> attr.isRegularFile() && p.toString().endsWith(".txt"))) {
            s.map(p -> p.getFileName().toString())
             .sorted()
             .forEach(n -> System.out.print(n + " "));
        }
    }
}
